def merge_sorted_streams(*streams):
    iterators = [iter(stream) for stream in streams]
    current = []
    for i, it in enumerate(iterators):
        try:
            current.append((next(it), i))
        except StopIteration:
            current.append((None, i))

    while any(item[0] is not None for item in current):
        min_item = min((item for item in current if item[0] is not None), key=lambda x: x[0])
        key, value = min_item[0]
        stream_idx = min_item[1]

        # Advance the stream that provided the minimum key
        try:
            next_item = next(iterators[stream_idx])
            current[stream_idx] = (next_item, stream_idx)
        except StopIteration:
            current[stream_idx] = (None, stream_idx)

        yield (key, value)
